head.script:
// 테스트 설명, 유효성 값 설정
//  _3 : Body 가 MultiLine 인 구성에서 columnInfo 파라미터의 Column 인덱스 고유성을 검증하는 분리 샘플
//       (_1 은 Column 인덱스 지정, _2 는 Column ID 지정 / 공통 유효성은 _1, _2 에서 검증)
scwin.tData = {
    "description" : "[gridView > M > setBlockSelect]<br/>Body Column 정보를 사용하여 특정 Column 의 blockSelect 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean 코드값 2 = true)
    par_block.setValue("2");

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄) 이며 한 데이터 Row 가 2줄에 걸쳐 표시됩니다. 두 줄에 나뉜 Column 이지만 인덱스는 이어져 부여됩니다 (1줄 col1=0 / col2=1, 2줄 col3=2 / col4=3).\n[절차] columnInfo / block 선택 -> setBlockSelect 실행 -> 차단한 Column 의 Body Cell 을 직접 클릭해 포커스가 잡히는지 확인 (다른 Column 의 Cell 도 클릭해 비교).\n[확인] Cell 클릭 시 실제 포커스 위치(Row / Column 인덱스)와 포커스 표시가 남아있는 Cell 목록이 출력됩니다. 2줄에 있는 Column 도 인덱스 2, 3 으로 지정되어 위/아래 줄의 Column 이 각각 구분 적용되는지 확인합니다."', '', 'label1');

    // dataList 생성 + 초기값 바인딩
    //  ※ createBasicDataList 는 col1~col4 (4컬럼) 스키마만 생성한다.
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "김민수", "col3": "2024-03-11", "col4": "A등급" },
        { "col1": "부산 해운대점", "col2": "이서연", "col3": "2024-05-02", "col4": "B등급" },
        { "col1": "대구 수성점", "col2": "박준호", "col3": "2024-07-19", "col4": "C등급" }
    ]);

    // target 생성
    //  ★ MultiLine : gBody 에 2개의 row 를 두어 한 데이터 Row 가 2줄에 걸쳐 표시되게 한다.
    //   1줄 : col1(인덱스 0) / col2(인덱스 1)
    //   2줄 : col3(인덱스 2) / col4(인덱스 3)
    //   -> 줄이 나뉘어도 Column 인덱스는 0~3 으로 고유하게 부여된다.
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" ev:oncellclick="scwin.target1_oncellclick" id="" style="width:560px;height:420px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="1줄 - 0 : col1 (지점명)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="1줄 - 1 : col2 (담당자)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="2줄 - 2 : col3 (등록일)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="2줄 - 3 : col4 (등급)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="280" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="280" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// setBlockSelect 실행 : Body 가 MultiLine 이어도 Column 인덱스는 줄에 걸쳐 고유하므로
//  지정한 인덱스가 어느 줄의 어떤 Column 으로 해석되었는지 Column ID 와 반영된 설정값을 함께 출력한다.
//  (쌍이 되는 get 메소드가 없어 getCellInfo 의 options.blockSelect 로 반영값을 확인한다.)
scwin.btn_setBlockSelect_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let block = (par_block.getText() === "true");

    scwin.target1.setBlockSelect(columnInfo, block);
    let colID = scwin.target1.getColumnID(columnInfo);
    let applied = scwin.target1.getCellInfo(columnInfo).options.blockSelect;

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setBlockSelect(" + columnInfo + ", " + block + ") -> 적용 Column ID : " + colID
        + " (" + (columnInfo < 2 ? "1줄" : "2줄") + "), 설정된 포커스 차단 여부 : " + applied);
}



// Body Cell 클릭 시 발생 : 클릭한 Cell 과 실제 포커스 상태를 대비 출력
//  MultiLine 이므로 같은 rowIndex 라도 columnIndex(0~3) 로 위/아래 줄의 Column 이 구분된다.
//  포커스가 차단된 Column 을 클릭하면 포커스가 그 Cell 로 이동하지 않는다.
scwin.target1_oncellclick = function (rowIndex, columnIndex, colID) {
    let focusedRow = scwin.target1.getFocusedRowIndex();
    let focusedCol = scwin.target1.getFocusedColumnIndex();

    // 포커스 표시(focusedTd) 가 남아있는 Cell 을 실측
    let markedList = [];
    let markedTds = scwin.target1.render.querySelectorAll("td.focusedTd");
    for (let i = 0; i < markedTds.length; i++) {
        let tdID = markedTds[i].id || "";
        markedList.push(tdID.substring(tdID.indexOf("cell_")));
    }

    wf_body_bottom.getObj("scwin").setReturnValue(
        "클릭 Cell : Row " + rowIndex + " / Column 인덱스 " + columnIndex + " (" + colID + ", " + (columnIndex < 2 ? "1줄" : "2줄") + ")"
        + " -> 실제 포커스 : Row " + focusedRow + " / Column 인덱스 " + focusedCol
        + ", 포커스 표시 Cell : [" + markedList.join(", ") + "]");
}
